def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[0][c] == grid[r][c] for r in range(h))]
    sep = grid[sep_rows[0]][0]
    row_starts = [0] + [r + 1 for r in sep_rows]
    col_starts = [0] + [c + 1 for c in sep_cols]
    row_ends = sep_rows + [h]
    col_ends = sep_cols + [w]

    # Find the patterned tile outside the first column of tiles.
    pattern_color = None
    for ti in range(len(row_starts)):
        for tj in range(1, len(col_starts)):
            vals = {
                grid[r][c]
                for r in range(row_starts[ti], row_ends[ti])
                for c in range(col_starts[tj], col_ends[tj])
                if grid[r][c] != 0 and grid[r][c] != sep
            }
            if vals:
                pattern_color = max(vals, key=lambda x: sum(
                    grid[r][c] == x
                    for r in range(row_starts[ti], row_ends[ti])
                    for c in range(col_starts[tj], col_ends[tj])
                ))
                break
        if pattern_color is not None:
            break

    tile_h = row_ends[0] - row_starts[0]
    tile_w = col_ends[0] - col_starts[0]
    mask = [
        [
            any(
                grid[r][c] == pattern_color
                for r in range(row_starts[ti], row_ends[ti])
                for c in range(col_starts[tj], col_ends[tj])
                if r - row_starts[ti] == i and c - col_starts[tj] == j
            )
            for j in range(tile_w)
        ]
        for i in range(tile_h)
    ]

    out = [[0] * w for _ in range(h)]
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]

    for ti in range(len(row_starts)):
        # The color in the first tile of each band supplies that band's output color.
        source = next(
            grid[r][c]
            for r in range(row_starts[ti], row_ends[ti])
            for c in range(col_starts[0], col_ends[0])
            if grid[r][c] not in (0, sep)
        )
        for tj in range(len(col_starts)):
            for i in range(tile_h):
                for j in range(tile_w):
                    if mask[i][j]:
                        out[row_starts[ti] + i][col_starts[tj] + j] = source
    return out
